package com.metcoffee.service;
import java.util.*; import org.springframework.stereotype.Service; import com.metcoffee.model.*; import com.metcoffee.dto.*; import com.metcoffee.repository.DireccionRepository;
@Service public class DomicilioService { private final DireccionRepository direcciones; public DomicilioService(DireccionRepository d){direcciones=d;} public DireccionDTO guardar(String usuario,DireccionDTO dto){validar(dto);Direccion d=new Direccion(dto.id(),usuario,dto.etiqueta(),dto.destinatario(),dto.direccion(),dto.telefono(),dto.principal());Direccion guardada=direcciones.save(d);if(guardada.isPrincipal()){for(Direccion direccion:direcciones.findByUsuarioId(usuario)){if(!direccion.getId().equals(guardada.getId())&&direccion.isPrincipal()){direccion.setPrincipal(false);direcciones.save(direccion);}}}return map(guardada);} public DireccionDTO actualizar(String usuario,String id,DireccionDTO dto){validar(dto);Direccion d=obtener(usuario,id);d.setEtiqueta(dto.etiqueta());d.setDestinatario(dto.destinatario());d.setDireccion(dto.direccion());d.setTelefono(dto.telefono());d.setPrincipal(dto.principal());Direccion actualizada=direcciones.save(d);if(actualizada.isPrincipal()){for(Direccion direccion:direcciones.findByUsuarioId(usuario)){if(!direccion.getId().equals(actualizada.getId())&&direccion.isPrincipal()){direccion.setPrincipal(false);direcciones.save(direccion);}}}return map(actualizada);} public List<DireccionDTO> listar(String usuario){return direcciones.findByUsuarioId(usuario).stream().map(this::map).toList();} public Direccion obtener(String usuario,String id){return direcciones.findByIdAndUsuarioId(id,usuario).orElseThrow(()->new IllegalArgumentException("Domicilio no encontrado"));} public void seleccionarPrincipal(String usuario,String id){obtener(usuario,id);for(Direccion direccion:direcciones.findByUsuarioId(usuario)){direccion.setPrincipal(direccion.getId().equals(id));direcciones.save(direccion);}} private void validar(DireccionDTO dto){if(dto==null||dto.direccion()==null||dto.direccion().isBlank()||dto.telefono()==null||dto.telefono().isBlank())throw new IllegalArgumentException("Domicilio inválido");} private DireccionDTO map(Direccion d){return new DireccionDTO(d.getId(),d.getEtiqueta(),d.getDestinatario(),d.getDireccion(),d.getTelefono(),d.isPrincipal());} }
